transshipment_gantry.source:
export const envelope = [24, 23, 16];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 5;
  const theme = api.theme;

  // World theme palette roles with clean fallbacks
  const gPavement = theme.ground?.pavement || "minecraft:stone_bricks";
  const gPlinth = theme.ground?.plinth || "minecraft:deepslate_bricks";
  const gCoping = theme.ground?.coping || "minecraft:stone_brick_slab";
  const gScree = theme.ground?.scree || theme.ground?.pavement || "minecraft:gravel";

  const sPrimary = theme.stone?.primary || "minecraft:stone_bricks";
  const sAccent = theme.stone?.accent || "minecraft:cracked_stone_bricks";
  const sStairs = theme.stone?.stairs || "minecraft:stone_brick_stairs";
  const sSlab = theme.stone?.slab || "minecraft:stone_brick_slab";
  const sWall = theme.stone?.wall || "minecraft:stone_brick_wall";

  const wPlanks = theme.wood?.planks || "minecraft:dark_oak_planks";
  const wLog = theme.wood?.log || "minecraft:dark_oak_log";
  const wStripped = theme.wood?.stripped || "minecraft:stripped_dark_oak_log";
  const wStairs = theme.wood?.stairs || "minecraft:dark_oak_stairs";
  const wSlab = theme.wood?.slab || "minecraft:dark_oak_slab";
  const wFence = theme.wood?.fence || "minecraft:dark_oak_fence";
  const wDoor = theme.wood?.door || "minecraft:dark_oak_door";
  const wTrapdoor = theme.wood?.trapdoor || "minecraft:dark_oak_trapdoor";

  const rSolid = theme.roof?.solid || "minecraft:deepslate_tiles";
  const rStairs = theme.roof?.stairs || "minecraft:deepslate_tile_stairs";

  // Safe placement within envelope
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Helper for applying block states to theme strings
  function st(block, state) {
    if (!block) return state;
    const base = block.split("[")[0];
    return `${base}[${state}]`;
  }

  // Foundation helper: connects terrain height at (x, z) up to yTop
  function groundColumn(x, z, yTop, block) {
    const gy = Math.max(0, Math.min(H - 1, SEAT_Y + api.heightAt(x, z)));
    const yStart = Math.min(gy, yTop);
    const yEnd = Math.max(gy, yTop);
    for (let y = yStart; y <= yEnd; y++) {
      set(x, y, z, block);
    }
  }

  // -------------------------------------------------------------
  // 1. GROUND SURFACES, RAIL SIDING, AND CANAL WHARF
  // -------------------------------------------------------------

  // Canal Wharf (X = 17 to 23, Z = 0 to 15)
  for (let x = 17; x <= 23; x++) {
    for (let z = 0; z <= 15; z++) {
      groundColumn(x, z, SEAT_Y, gPavement);
    }
  }
  for (let z = 0; z <= 15; z++) {
    set(17, SEAT_Y, z, gCoping);
  }
  // Dock bollards
  const bollardZ = [1, 6, 10, 14];
  for (const bz of bollardZ) {
    set(17, SEAT_Y + 1, bz, sWall);
    set(17, SEAT_Y + 2, bz, "minecraft:heavy_weighted_pressure_plate");
  }

  // Rail Sidings (X = 1 to 6, Z = 0 to 15)
  for (let x = 1; x <= 6; x++) {
    for (let z = 0; z <= 15; z++) {
      groundColumn(x, z, SEAT_Y, gScree);
    }
  }
  // Rail track bed and rails (x = 3, 4)
  for (let z = 0; z <= 15; z++) {
    groundColumn(3, z, SEAT_Y, sAccent);
    groundColumn(4, z, SEAT_Y, sAccent);
    if (z <= 13) {
      set(3, SEAT_Y + 1, z, "minecraft:rail[shape=north_south]");
      set(4, SEAT_Y + 1, z, "minecraft:rail[shape=north_south]");
    }
  }
  // Rail buffer stop at south end
  for (let x = 3; x <= 4; x++) {
    set(x, SEAT_Y + 1, 14, st(wLog, "axis=x"));
    set(x, SEAT_Y + 2, 14, st(wLog, "axis=x"));
    groundColumn(x, 15, SEAT_Y + 2, sPrimary);
  }
  set(3, SEAT_Y + 2, 13, "minecraft:iron_bars");
  set(4, SEAT_Y + 2, 13, "minecraft:iron_bars");

  // Central Transshipment Yard Paving (X = 7 to 16, Z = 0 to 15)
  for (let x = 7; x <= 16; x++) {
    for (let z = 0; z <= 15; z++) {
      groundColumn(x, z, SEAT_Y, gPavement);
    }
  }
  // Soot and coal piles under the loading chutes
  for (let x = 11; x <= 15; x++) {
    for (let z = 6; z <= 9; z++) {
      set(x, SEAT_Y, z, "minecraft:coal_block");
    }
  }
  set(12, SEAT_Y + 1, 7, "minecraft:coal_block");
  set(13, SEAT_Y + 1, 8, "minecraft:coal_block");
  set(14, SEAT_Y + 1, 7, "minecraft:coal_block");
  set(14, SEAT_Y + 1, 8, "minecraft:coal_block");

  // -------------------------------------------------------------
  // 2. MASSIVE MASONRY PIERS (4 CORNERS)
  // -------------------------------------------------------------
  const piers = [
    { px: 2, pz: 1 },   // NW Rail
    { px: 2, pz: 12 },  // SW Rail
    { px: 18, pz: 1 },  // NE Canal
    { px: 18, pz: 12 }, // SE Canal
  ];

  for (const { px, pz } of piers) {
    for (let dx = 0; dx < 3; dx++) {
      for (let dz = 0; dz < 3; dz++) {
        groundColumn(px + dx, pz + dz, SEAT_Y + 1, sPrimary);
      }
    }
    // Raised central mounting plinth
    set(px + 1, SEAT_Y + 2, pz + 1, sAccent);

    // Beveled perimeter stairs at pedestal top
    for (let dx = 0; dx < 3; dx++) {
      set(px + dx, SEAT_Y + 2, pz, st(sStairs, "facing=north,half=bottom"));
      set(px + dx, SEAT_Y + 2, pz + 2, st(sStairs, "facing=south,half=bottom"));
    }
    set(px, SEAT_Y + 2, pz + 1, st(sStairs, "facing=west,half=bottom"));
    set(px + 2, SEAT_Y + 2, pz + 1, st(sStairs, "facing=east,half=bottom"));
    set(px, SEAT_Y + 2, pz, gPlinth);
    set(px + 2, SEAT_Y + 2, pz, gPlinth);
    set(px, SEAT_Y + 2, pz + 2, gPlinth);
    set(px + 2, SEAT_Y + 2, pz + 2, gPlinth);
  }

  // -------------------------------------------------------------
  // 3. GANTRY A-FRAME LEGS & TRUSSES
  // -------------------------------------------------------------
  const yLegBase = SEAT_Y + 2;
  const yGantryDeck = SEAT_Y + 9;

  // West Towers (Rail Side)
  for (let y = yLegBase; y <= yGantryDeck; y++) {
    // Outer vertical posts
    set(3, y, 2, st(wLog, "axis=y"));
    set(3, y, 13, st(wLog, "axis=y"));

    // Inward diagonal braces
    if (y <= yLegBase + 2) {
      set(5, y, 2, st(wLog, "axis=y"));
      set(5, y, 13, st(wLog, "axis=y"));
    } else if (y <= yLegBase + 5) {
      set(4, y, 2, st(wLog, "axis=y"));
      set(4, y, 13, st(wLog, "axis=y"));
    } else {
      set(3, y, 2, st(wLog, "axis=y"));
      set(3, y, 13, st(wLog, "axis=y"));
    }
  }

  // East Towers (Canal Side)
  for (let y = yLegBase; y <= yGantryDeck; y++) {
    // Outer vertical posts
    set(19, y, 2, st(wLog, "axis=y"));
    set(19, y, 13, st(wLog, "axis=y"));

    // Inward diagonal braces
    if (y <= yLegBase + 2) {
      set(17, y, 2, st(wLog, "axis=y"));
      set(17, y, 13, st(wLog, "axis=y"));
    } else if (y <= yLegBase + 5) {
      set(18, y, 2, st(wLog, "axis=y"));
      set(18, y, 13, st(wLog, "axis=y"));
    } else {
      set(19, y, 2, st(wLog, "axis=y"));
      set(19, y, 13, st(wLog, "axis=y"));
    }
  }

  // Horizontal tie beams and truss infill along Z
  const tieY = [SEAT_Y + 5, SEAT_Y + 8];
  for (const ty of tieY) {
    for (let z = 2; z <= 13; z++) {
      set(3, ty, z, st(wStripped, "axis=z"));
      set(19, ty, z, st(wStripped, "axis=z"));
    }
  }
  // Iron truss cross-bracing in tower frames
  for (let z = 3; z <= 12; z++) {
    if (z !== 7 && z !== 8) {
      set(3, SEAT_Y + 4, z, "minecraft:iron_bars");
      set(3, SEAT_Y + 6, z, "minecraft:iron_bars");
      set(3, SEAT_Y + 7, z, "minecraft:iron_bars");
      set(19, SEAT_Y + 4, z, "minecraft:iron_bars");
      set(19, SEAT_Y + 6, z, "minecraft:iron_bars");
      set(19, SEAT_Y + 7, z, "minecraft:iron_bars");
    }
  }

  // Safety cage ladder on NW Tower
  for (let y = SEAT_Y + 1; y <= SEAT_Y + 10; y++) {
    set(2, y, 2, st(wLog, "axis=y"));
    set(2, y, 3, "minecraft:ladder[facing=south]");
    set(1, y, 3, "minecraft:iron_bars");
    set(2, y, 4, "minecraft:iron_bars");
  }

  // -------------------------------------------------------------
  // 4. OVERHEAD GANTRY BRIDGE & RUNWAYS (X = 2 to 21)
  // -------------------------------------------------------------
  const yGirderBot = SEAT_Y + 9;
  const yGirderTop = SEAT_Y + 11;

  for (let x = 2; x <= 21; x++) {
    // North Longitudinal Box Girder (Z = 2..3)
    set(x, yGirderBot, 3, st(wStripped, "axis=x"));
    set(x, yGirderBot, 2, st(wLog, "axis=x"));
    set(x, yGirderTop, 3, st(wStripped, "axis=x"));
    set(x, yGirderTop, 2, st(wLog, "axis=x"));
    set(x, yGirderBot + 1, 2, (x % 2 === 0) ? sWall : "minecraft:iron_bars");
    set(x, yGirderBot + 1, 3, (x % 3 === 0) ? st(wLog, "axis=y") : "minecraft:iron_bars");
    if (x >= 3 && x <= 20) {
      set(x, yGirderTop + 1, 2, "minecraft:rail[shape=east_west]");
    }

    // South Longitudinal Box Girder (Z = 12..13)
    set(x, yGirderBot, 12, st(wStripped, "axis=x"));
    set(x, yGirderBot, 13, st(wLog, "axis=x"));
    set(x, yGirderTop, 12, st(wStripped, "axis=x"));
    set(x, yGirderTop, 13, st(wLog, "axis=x"));
    set(x, yGirderBot + 1, 13, (x % 2 === 0) ? sWall : "minecraft:iron_bars");
    set(x, yGirderBot + 1, 12, (x % 3 === 0) ? st(wLog, "axis=y") : "minecraft:iron_bars");
    if (x >= 3 && x <= 20) {
      set(x, yGirderTop + 1, 13, "minecraft:rail[shape=east_west]");
    }
  }

  // Transverse deck cross-beams
  for (let x = 3; x <= 21; x += 2) {
    for (let z = 3; z <= 12; z++) {
      set(x, yGirderBot, z, st(wLog, "axis=z"));
    }
  }

  // Catwalk deck and safety railings
  for (let x = 2; x <= 21; x++) {
    set(x, yGirderBot + 1, 4, wPlanks);
    set(x, yGirderBot + 1, 11, wPlanks);
    if (x !== 8) { // doorway opening at x=8
      set(x, yGirderBot + 2, 4, wFence);
    }
    set(x, yGirderBot + 2, 11, wFence);
  }

  // -------------------------------------------------------------
  // 5. OPERATOR'S CONTROL CABIN (X = 7..12, Z = 5..10)
  // -------------------------------------------------------------
  // Floor at y = SEAT_Y + 9 (y = 14)
  for (let x = 7; x <= 12; x++) {
    for (let z = 5; z <= 10; z++) {
      set(x, SEAT_Y + 9, z, wPlanks);
    }
  }

  // Cabin exterior walls (y = 15..17)
  for (let y = SEAT_Y + 10; y <= SEAT_Y + 12; y++) {
    for (let x = 7; x <= 12; x++) {
      set(x, y, 5, wPlanks);
      set(x, y, 10, wPlanks);
    }
    for (let z = 5; z <= 10; z++) {
      set(7, y, z, wPlanks);
      set(12, y, z, wPlanks);
    }
  }

  // Windows & Doorway
  set(8, SEAT_Y + 10, 5, st(wDoor, "facing=north,half=lower,open=false"));
  set(8, SEAT_Y + 11, 5, st(wDoor, "facing=north,half=upper,open=false"));
  set(10, SEAT_Y + 11, 5, "minecraft:iron_bars");
  set(9, SEAT_Y + 11, 10, "minecraft:iron_bars");
  set(10, SEAT_Y + 11, 10, "minecraft:iron_bars");
  set(7, SEAT_Y + 11, 7, "minecraft:iron_bars");
  set(7, SEAT_Y + 11, 8, "minecraft:iron_bars");

  // Ceiling & Shed Roof (y = 18..19)
  for (let x = 7; x <= 12; x++) {
    for (let z = 5; z <= 10; z++) {
      set(x, SEAT_Y + 13, z, wPlanks);
    }
  }
  for (let x = 6; x <= 13; x++) {
    set(x, SEAT_Y + 14, 4, st(rStairs, "facing=south,half=bottom"));
    for (let z = 5; z <= 10; z++) {
      set(x, SEAT_Y + 14, z, rSolid);
    }
    set(x, SEAT_Y + 14, 11, st(rStairs, "facing=north,half=bottom"));
  }

  // Cabin Stovepipe Chimney
  set(7, SEAT_Y + 13, 9, "minecraft:hopper[facing=down]");
  set(7, SEAT_Y + 14, 9, "minecraft:cauldron");
  set(7, SEAT_Y + 15, 9, "minecraft:iron_bars");

  // -------------------------------------------------------------
  // 6. SOOT-CAKED COAL HOPPER & DISCHARGE CHUTE
  // -------------------------------------------------------------
  // Hopper Upper Box (Y = SEAT_Y + 10 .. SEAT_Y + 12)
  for (let y = SEAT_Y + 10; y <= SEAT_Y + 12; y++) {
    for (let x = 13; x <= 16; x++) {
      set(x, y, 5, sAccent);
      set(x, y, 10, sAccent);
    }
    for (let z = 5; z <= 10; z++) {
      set(13, y, z, sAccent);
      set(16, y, z, sAccent);
    }
  }
  // Coal inside upper hopper
  for (let x = 14; x <= 15; x++) {
    for (let z = 6; z <= 9; z++) {
      set(x, SEAT_Y + 10, z, "minecraft:coal_block");
      set(x, SEAT_Y + 11, z, "minecraft:coal_block");
    }
  }

  // Sloping Inverted Funnel (Y = SEAT_Y + 8 .. SEAT_Y + 9)
  for (let x = 14; x <= 15; x++) {
    set(x, SEAT_Y + 9, 6, st(sStairs, "facing=south,half=top"));
    set(x, SEAT_Y + 9, 9, st(sStairs, "facing=north,half=top"));
    set(x, SEAT_Y + 9, 7, "minecraft:coal_block");
    set(x, SEAT_Y + 9, 8, "minecraft:coal_block");
  }
  for (let z = 7; z <= 8; z++) {
    set(13, SEAT_Y + 9, z, st(sStairs, "facing=east,half=top"));
    set(16, SEAT_Y + 9, z, st(sStairs, "facing=west,half=top"));
  }

  // Chute outlet spouts toward the rail track
  for (let z = 7; z <= 8; z++) {
    set(14, SEAT_Y + 8, z, "minecraft:hopper[facing=west]");
    set(15, SEAT_Y + 8, z, "minecraft:hopper[facing=west]");
    set(13, SEAT_Y + 7, z, st(sStairs, "facing=east,half=bottom"));
    set(12, SEAT_Y + 6, z, "minecraft:hopper[facing=west]");
    set(11, SEAT_Y + 5, z, "minecraft:iron_bars");
  }

  // -------------------------------------------------------------
  // 7. WINCH GEAR & CANTILEVER JIB BOOM
  // -------------------------------------------------------------
  // Winch Deck and Steam Machinery
  for (let x = 15; x <= 17; x++) {
    for (let z = 6; z <= 9; z++) {
      set(x, SEAT_Y + 12, z, sAccent);
    }
  }
  set(16, SEAT_Y + 12, 6, "minecraft:blast_furnace[facing=north]");
  set(16, SEAT_Y + 13, 6, "minecraft:hopper[facing=down]");
  set(15, SEAT_Y + 12, 7, "minecraft:grindstone[face=floor,facing=north]");
  set(15, SEAT_Y + 12, 8, "minecraft:grindstone[face=floor,facing=north]");
  set(16, SEAT_Y + 12, 7, "minecraft:anvil[facing=north]");
  set(16, SEAT_Y + 12, 8, "minecraft:anvil[facing=north]");
  set(16, SEAT_Y + 12, 9, gPlinth);
  set(16, SEAT_Y + 13, 9, gPlinth);

  // Cantilever Jib Boom extending over Canal (X = 18 to 22)
  for (let x = 18; x <= 22; x++) {
    set(x, SEAT_Y + 11, 7, st(wLog, "axis=x"));
    set(x, SEAT_Y + 11, 8, st(wLog, "axis=x"));
  }
  for (let x = 17; x <= 21; x++) {
    set(x, SEAT_Y + 13, 7, "minecraft:iron_bars");
    set(x, SEAT_Y + 13, 8, "minecraft:iron_bars");
  }
  set(21, SEAT_Y + 12, 7, "minecraft:grindstone[face=ceiling,facing=east]");
  set(21, SEAT_Y + 12, 8, "minecraft:grindstone[face=ceiling,facing=east]");
  set(22, SEAT_Y + 12, 7, "minecraft:lantern[hanging=true]");

  // -------------------------------------------------------------
  // 8. SUSPENDED COAL CLAMSHELL BUCKET OVER CANAL
  // -------------------------------------------------------------
  // Chains dropping from jib
  for (let y = SEAT_Y + 5; y <= SEAT_Y + 10; y++) {
    set(21, y, 7, "minecraft:chain[axis=y]");
    set(21, y, 8, "minecraft:chain[axis=y]");
  }
  // Clamshell spreader bridle
  set(21, SEAT_Y + 4, 7, "minecraft:hopper[facing=down]");
  set(21, SEAT_Y + 4, 8, "minecraft:hopper[facing=down]");

  // Clamshell grab bucket holding coal
  set(21, SEAT_Y + 3, 7, "minecraft:cauldron");
  set(21, SEAT_Y + 3, 8, "minecraft:cauldron");
  set(20, SEAT_Y + 3, 7, st(wTrapdoor, "facing=east,half=bottom,open=true"));
  set(20, SEAT_Y + 3, 8, st(wTrapdoor, "facing=east,half=bottom,open=true"));
  set(22, SEAT_Y + 3, 7, st(wTrapdoor, "facing=west,half=bottom,open=true"));
  set(22, SEAT_Y + 3, 8, st(wTrapdoor, "facing=west,half=bottom,open=true"));

  set(21, SEAT_Y + 2, 7, "minecraft:coal_block");
  set(21, SEAT_Y + 2, 8, "minecraft:coal_block");
  set(21, SEAT_Y + 2, 6, st(wTrapdoor, "facing=south,half=bottom,open=true"));
  set(21, SEAT_Y + 2, 9, st(wTrapdoor, "facing=north,half=bottom,open=true"));

  // -------------------------------------------------------------
  // 9. SUSPENDED CARGO HOIST OVER YARD (X = 10)
  // -------------------------------------------------------------
  for (let y = SEAT_Y + 5; y <= SEAT_Y + 9; y++) {
    set(10, y, 7, "minecraft:chain[axis=y]");
  }
  for (let x = 9; x <= 11; x++) {
    set(x, SEAT_Y + 4, 7, "minecraft:iron_bars");
  }
  // Timber freight crate
  for (let x = 9; x <= 10; x++) {
    for (let z = 7; z <= 8; z++) {
      set(x, SEAT_Y + 3, z, wPlanks);
      set(x, SEAT_Y + 2, z, wPlanks);
    }
  }
  set(8, SEAT_Y + 3, 7, st(wTrapdoor, "facing=east,half=bottom,open=true"));
  set(8, SEAT_Y + 3, 8, st(wTrapdoor, "facing=east,half=bottom,open=true"));
  set(11, SEAT_Y + 3, 7, st(wTrapdoor, "facing=west,half=bottom,open=true"));
  set(11, SEAT_Y + 3, 8, st(wTrapdoor, "facing=west,half=bottom,open=true"));

  // -------------------------------------------------------------
  // 10. INDUSTRIAL LIGHTING & DETAILS
  // -------------------------------------------------------------
  set(4, SEAT_Y + 8, 4, "minecraft:lantern[hanging=true]");
  set(4, SEAT_Y + 8, 11, "minecraft:lantern[hanging=true]");
  set(18, SEAT_Y + 8, 4, "minecraft:lantern[hanging=true]");
  set(18, SEAT_Y + 8, 11, "minecraft:lantern[hanging=true]");
  set(8, SEAT_Y + 11, 4, "minecraft:lantern[hanging=true]");
  set(17, SEAT_Y + 2, 3, "minecraft:lantern[hanging=false]");
  set(17, SEAT_Y + 2, 12, "minecraft:lantern[hanging=false]");

  return {
    name: "transshipment_gantry",
    seatY: SEAT_Y,
    anchors: {
      front: [12, SEAT_Y, 0],
      rail: [4, SEAT_Y, 0],
      canal: [19, SEAT_Y, 0],
      cabin: [8, SEAT_Y + 10, 5],
    },
    interiors: [
      {
        min: [8, SEAT_Y + 10, 6],
        max: [11, SEAT_Y + 12, 9],
        kind: "bridge",
      },
    ],
  };
}

