export const envelope = [9, 32, 9];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const cx = 4;
  const cz = 4;
  const seatY = 6;

  const inst = (api.instance && typeof api.instance.index === "number")
    ? (api.instance.index % 5)
    : 0;

  const rand = () => api.random();

  // Safe block writer respecting envelope bounds
  function set(x, y, z, block) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < sizeX && iy >= 0 && iy < sizeY && iz >= 0 && iz < sizeZ) {
      api.set(ix, iy, iz, block);
    }
  }

  // World theme palette extraction
  const stonePrimary = api.theme.stone.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:deepslate_bricks";
  const plinthBlock = api.theme.ground.plinth || stonePrimary;

  // Brick & masonry variants
  const brickPalette = [
    "minecraft:bricks",
    "minecraft:bricks",
    "minecraft:mud_bricks",
    "minecraft:brown_terracotta",
    "minecraft:terracotta",
    stonePrimary
  ];

  // Soot & industrial char variants
  const sootPalette = [
    "minecraft:deepslate_bricks",
    "minecraft:cracked_deepslate_bricks",
    "minecraft:polished_blackstone_bricks",
    "minecraft:cracked_polished_blackstone_bricks",
    "minecraft:blackstone",
    "minecraft:basalt[axis=y]",
    "minecraft:coal_block"
  ];

  function pickBrick(sootLevel) {
    if (sootLevel > 0.65) {
      const idx = Math.floor(rand() * 4) + 3;
      return sootPalette[Math.min(idx, sootPalette.length - 1)];
    } else if (sootLevel > 0.35) {
      const idx = Math.floor(rand() * 4);
      return sootPalette[idx];
    } else {
      const idx = Math.floor(rand() * brickPalette.length);
      return brickPalette[idx];
    }
  }

  // --- 1. Footprint & Ground Adaptation (Rule 6) ---
  // 7x7 chamfered octagonal base footprint
  for (let dx = -3; dx <= 3; dx++) {
    for (let dz = -3; dz <= 3; dz++) {
      if (Math.abs(dx) + Math.abs(dz) <= 5) {
        const gx = cx + dx;
        const gz = cz + dz;
        const groundH = api.heightAt(gx, gz);
        const groundY = Math.max(0, Math.min(sizeY - 1, seatY + Math.floor(groundH)));

        // Extend solid foundation down to ground / seabed
        const minY = Math.min(groundY, seatY);
        const maxY = Math.max(groundY, seatY);
        for (let y = minY; y <= maxY; y++) {
          set(gx, y, gz, plinthBlock);
        }
      }
    }
  }

  // --- 2. Base Plinth & Pedestal ---
  const plinthH = 3 + (inst % 2);
  const shaftStartY = seatY + plinthH;

  for (let y = seatY; y < shaftStartY; y++) {
    const isTopCourse = (y === shaftStartY - 1);
    for (let dx = -3; dx <= 3; dx++) {
      for (let dz = -3; dz <= 3; dz++) {
        const distSum = Math.abs(dx) + Math.abs(dz);
        if (distSum <= 5) {
          const bx = cx + dx;
          const bz = cz + dz;
          if (isTopCourse && distSum === 5) {
            // Chamfered ledge at top of plinth
            set(bx, y, bz, stoneAccent);
          } else if (isTopCourse && (Math.abs(dx) === 3 || Math.abs(dz) === 3)) {
            // Stepped transition into the shaft
            if (dz === -3) set(bx, y, bz, "minecraft:stone_brick_stairs[facing=north,half=bottom]");
            else if (dz === 3) set(bx, y, bz, "minecraft:stone_brick_stairs[facing=south,half=bottom]");
            else if (dx === -3) set(bx, y, bz, "minecraft:stone_brick_stairs[facing=west,half=bottom]");
            else if (dx === 3) set(bx, y, bz, "minecraft:stone_brick_stairs[facing=east,half=bottom]");
            else set(bx, y, bz, stonePrimary);
          } else {
            const block = (rand() < 0.3) ? stoneAccent : plinthBlock;
            set(bx, y, bz, block);
          }
        }
      }
    }
  }

  // Instance specific base features:
  // Inst 1 & 4: Arched brick flue intake duct on South side (connecting to furnace)
  if (inst === 1 || inst === 4) {
    for (let dy = 0; dy <= 2; dy++) {
      const fy = seatY + dy;
      set(cx - 1, fy, cz + 3, "minecraft:bricks");
      set(cx + 1, fy, cz + 3, "minecraft:bricks");
      if (dy === 2) {
        set(cx, fy, cz + 3, "minecraft:deepslate_bricks");
      } else {
        set(cx, fy, cz + 3, "minecraft:iron_bars");
      }
    }
  } else {
    // Iron cleanout hatch on North face
    set(cx, seatY + 1, cz - 3, "minecraft:iron_trapdoor[facing=north,half=bottom,open=false]");
  }

  // --- 3. Tapering Smokestack Shaft ---
  const stackTopY = seatY + 17 + ((inst * 2) % 5); // 23 to 27
  const rBase = 2.25;
  const rTop = 1.4;

  const bandInterval = 4;
  const hasPlatform = (inst === 1 || inst === 4);

  for (let y = shaftStartY; y <= stackTopY; y++) {
    const t = (y - shaftStartY) / (stackTopY - shaftStartY);
    const outerR = rBase - (rBase - rTop) * t;
    const innerR = Math.max(0.65, outerR - 0.85);
    const isBand = ((y - shaftStartY) % bandInterval === 0) && (y < stackTopY - 1);

    const sootFactor = Math.pow(t, 1.5);
    const instanceSootBias = 0.2 + 0.12 * inst;

    for (let dx = -3; dx <= 3; dx++) {
      for (let dz = -3; dz <= 3; dz++) {
        const dist = Math.hypot(dx, dz);
        const bx = cx + dx;
        const bz = cz + dz;

        if (dist <= outerR + 0.35 && dist >= innerR) {
          if (isBand) {
            set(bx, y, bz, "minecraft:polished_blackstone_bricks");
          } else {
            const sootProb = sootFactor * 0.85 + instanceSootBias * 0.3 + (rand() * 0.2 - 0.1);
            set(bx, y, bz, pickBrick(sootProb));
          }
        }
      }
    }

    // Outer iron reinforcement hoop fittings on banding levels
    if (isBand) {
      const hoopR = Math.round(outerR);
      set(cx, y, cz - hoopR - 1, "minecraft:iron_bars");
      set(cx, y, cz + hoopR + 1, "minecraft:iron_bars");
      set(cx - hoopR - 1, y, cz, "minecraft:iron_bars");
      set(cx + hoopR + 1, y, cz, "minecraft:iron_bars");
    }
  }

  // --- 4. Vertical Iron Maintenance Ladder (North Face) ---
  for (let y = seatY + 1; y < stackTopY; y++) {
    const t = (y - shaftStartY) / (stackTopY - shaftStartY);
    const curR = (y < shaftStartY) ? 2.5 : (rBase - (rBase - rTop) * Math.max(0, t));
    const wallZ = cz - Math.round(curR);
    const ladderZ = wallZ - 1;

    if (ladderZ >= 0) {
      // Ensure solid anchor behind ladder
      set(cx, y, wallZ, (y >= shaftStartY) ? "minecraft:deepslate_bricks" : stonePrimary);
      set(cx, y, ladderZ, "minecraft:ladder[facing=north]");

      // Safety cage rings every 3 blocks (instances 0, 2, 3)
      if ((inst === 0 || inst === 2 || inst === 3) && y % 3 === 0 && y > seatY + 2 && y < stackTopY - 1) {
        set(cx - 1, y, ladderZ, "minecraft:iron_bars");
        set(cx + 1, y, ladderZ, "minecraft:iron_bars");
        if (ladderZ - 1 >= 0) {
          set(cx, y, ladderZ - 1, "minecraft:iron_bars");
        }
      }
    }
  }

  // --- 5. Maintenance Catwalk Platform (Instances 1 & 4) ---
  if (hasPlatform) {
    const platY = stackTopY - 2;
    for (let dx = -3; dx <= 3; dx++) {
      for (let dz = -3; dz <= 3; dz++) {
        const dist = Math.hypot(dx, dz);
        if (dist >= 1.7 && dist <= 2.8) {
          const px = cx + dx;
          const pz = cz + dz;
          set(px, platY, pz, "minecraft:iron_trapdoor[half=bottom,open=false]");
          if (dist >= 2.4) {
            set(px, platY + 1, pz, "minecraft:iron_bars");
          }
        }
      }
    }
  }

  // --- 6. Chimney Crown & Flared Corbel Rim ---
  // Under-rim corbel brackets
  set(cx, stackTopY - 1, cz - 2, "minecraft:polished_blackstone_brick_stairs[facing=north,half=top]");
  set(cx, stackTopY - 1, cz + 2, "minecraft:polished_blackstone_brick_stairs[facing=south,half=top]");
  set(cx - 2, stackTopY - 1, cz, "minecraft:polished_blackstone_brick_stairs[facing=west,half=top]");
  set(cx + 2, stackTopY - 1, cz, "minecraft:polished_blackstone_brick_stairs[facing=east,half=top]");

  // Flared corbelled crown rim
  const rCrown = rTop + 0.75;
  for (let dx = -2; dx <= 2; dx++) {
    for (let dz = -2; dz <= 2; dz++) {
      const dist = Math.hypot(dx, dz);
      if (dist <= rCrown && dist >= 0.65) {
        set(cx + dx, stackTopY, cz + dz, "minecraft:polished_blackstone_bricks");
      }
    }
  }

  // Internal signal campfire inside top of flue for live particle smoke
  set(cx, stackTopY - 2, cz, "minecraft:hay_block");
  set(cx, stackTopY - 1, cz, "minecraft:campfire[lit=true,signal_fire=true]");

  // --- 7. Billowing Coal Smoke Plume (Voxel Cloud) ---
  const windVectors = [
    [0.35, -0.35],  // inst 0: North-East
    [-0.40, 0.30],  // inst 1: South-West
    [0.42, 0.22],   // inst 2: South-East
    [0.10, -0.45],  // inst 3: North
    [-0.35, -0.35]  // inst 4: North-West
  ];

  const [wX, wZ] = windVectors[inst];

  for (let y = stackTopY; y < sizeY; y++) {
    const progress = (y - stackTopY) / Math.max(1, sizeY - 1 - stackTopY);
    const driftDist = (y - stackTopY) * 0.22;
    const puffCenterX = cx + wX * driftDist + Math.sin(progress * 4.0 + inst) * 0.3;
    const puffCenterZ = cz + wZ * driftDist + Math.cos(progress * 4.0 + inst) * 0.3;
    const puffRadius = 0.85 + 0.65 * progress;

    for (let dx = -2; dx <= 2; dx++) {
      for (let dz = -2; dz <= 2; dz++) {
        const sx = Math.round(puffCenterX + dx);
        const sz = Math.round(puffCenterZ + dz);
        const dist = Math.hypot(sx - puffCenterX, sz - puffCenterZ);

        if (dist <= puffRadius) {
          if (y === stackTopY && dist < 0.7) {
            // Keep central flue opening clear for campfire smoke flow
            continue;
          }

          if (dist <= 0.45 * puffRadius) {
            // Dense black core
            const r = rand();
            if (r < 0.45) set(sx, y, sz, "minecraft:black_wool");
            else if (r < 0.75) set(sx, y, sz, "minecraft:coal_block");
            else set(sx, y, sz, "minecraft:tinted_glass");
          } else if (dist <= 0.8 * puffRadius) {
            // Medium gray smoke mantle
            const r = rand();
            if (r < 0.35) set(sx, y, sz, "minecraft:gray_wool");
            else if (r < 0.70) set(sx, y, sz, "minecraft:black_stained_glass");
            else set(sx, y, sz, "minecraft:gray_stained_glass");
          } else {
            // Outer turbulent wisps
            if (rand() < 0.65) {
              const r = rand();
              if (r < 0.45) set(sx, y, sz, "minecraft:cobweb");
              else if (r < 0.75) set(sx, y, sz, "minecraft:gray_stained_glass");
              else set(sx, y, sz, "minecraft:black_stained_glass");
            }
          }
        }
      }
    }
  }

  return {
    name: "factory_smokestack",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
      flue_intake: [cx, seatY, 7],
      crown: [cx, stackTopY, cz]
    }
  };
}
